begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local s1.tap='on';
select no_plan();
\ir s4_fixture.sql
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','Early',2000,'Synthetic','0000','A')$q$)='S4008','owner cannot create v2 settlement before confirmation');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement('24000000-0000-4000-8000-000000000001','Early',2000,'Synthetic','0000','A')$q$)='S4008','owner cannot create legacy settlement before confirmation');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','Early',2000,'Synthetic','0000','B')$q$)='S4008','mate cannot create v2 settlement before confirmation');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement('24000000-0000-4000-8000-000000000001','Early',2000,'Synthetic','0000','B')$q$)='S4008','mate cannot create legacy settlement before confirmation');
reset role;
select pg_temp.check((select stage='scheduling' from public.rooms where id='24000000-0000-4000-8000-000000000001') and not exists(select 1 from public.dutch_pay_bills where room_id='24000000-0000-4000-8000-000000000001'),'preconfirmation rejection has no bill or stage effect');
-- Privileged fixture models a pre-existing place room with no usable schedule.
update public.rooms set stage='place' where id='24000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'permissions'->>'can_submit'='true','unselected place advertises schedule recovery');
select pg_temp.check(pg_temp.s4_submit('24000000-0000-4000-8000-000000000001')->>'outcome'='applied','new submit RPC recovers unselected place schedule');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.set_my_availability('24000000-0000-4000-8000-000000000001',array(select jsonb_array_elements_text(v) from s4_data where k='slots'));
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'availability'->>'all_submitted'='true','legacy submit RPC also recovers place without a selected time');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','Early place',2000,'Synthetic','0000','B')$q$)='S4008','place schedule recovery does not open settlement');
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of(format($q$select public.add_voting_item('24000000-0000-4000-8000-000000000001','menu',%L)$q$,label))='S4002','reject invalid candidate label: '||reason)
from (values(E'\t\n','tab/newline only'),(E'Cafe\nInjected','embedded newline'),(chr(1)||'Cafe','C0 control'),('Cafe'||chr(127),'DEL'),('   ','spaces only')) cases(label,reason);
insert into s4_data values('review-menu',to_jsonb(public.add_voting_item('24000000-0000-4000-8000-000000000001','menu',chr(8195)||'  Review restaurant  '||chr(8195))));
reset role;
select pg_temp.check((select v->>'label'='Review restaurant' from public.rooms r cross join lateral jsonb_array_elements(r.voting_items) v where r.id='24000000-0000-4000-8000-000000000001' and v->>'id'=(select v#>>'{}' from s4_data where k='review-menu')),'POSIX whitespace is trimmed before storing a candidate');
set local role authenticated;
select public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',(select v from s4_data where k='time'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid());
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'permissions'->>'can_submit'='false','selecting a time closes schedule recovery');
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_submit('24000000-0000-4000-8000-000000000001')$q$)='S4003','new schedule submit is closed after time selection');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_my_availability('24000000-0000-4000-8000-000000000001','{}')$q$)='S4003','legacy schedule withdrawal is closed after time selection');
select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='review-menu'));
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='review-menu'));
reset role;
update public.rooms set voting_items=jsonb_set(voting_items,'{0,label}',to_jsonb(E'Legacy\nInjected'::text)) where id='24000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='review-menu'))$q$)='S4002','legacy control label cannot be injected into a confirmation event');
reset role;
select pg_temp.check(not exists(select 1 from public.messages where event_key='appointment-confirmed:24000000-0000-4000-8000-000000000001'),'invalid legacy label emits no event');
update public.rooms set voting_items=jsonb_set(voting_items,'{0,label}','"Review restaurant"') where id='24000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.confirm_room_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='review-menu'));
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
insert into s4_data values('review-bill',to_jsonb(public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','Review bill',2000,'Synthetic','0000','B')));
select pg_temp.check(public.create_room_settlement('24000000-0000-4000-8000-000000000001','Review bill',2000,'Synthetic','0000','B')=(select (v#>>'{}')::uuid from s4_data where k='review-bill'),'confirmed-room mate may create and retry through legacy settlement RPC');
reset role;
select pg_temp.check((select count(*)=2 and bool_and(profile_id is not null) from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='review-bill')),'NULL-profile display row is excluded from recipient snapshot');
select pg_temp.check((select split_count=2 from public.dutch_pay_bills where id=(select (v#>>'{}')::uuid from s4_data where k='review-bill')),'settlement quorum counts only actual recipients');
select pg_temp.check((select stage='settling' from public.rooms where id='24000000-0000-4000-8000-000000000001'),'confirmed room transitions to settling after allowed creation');
set local role authenticated;
select public.set_settlement_completed(id,true) from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='review-bill');
insert into s4_data values('review-next-bill',to_jsonb(public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','New done bill',2000,'Synthetic','0000','B')));
select pg_temp.check((select v from s4_data where k='review-next-bill')<>(select v from s4_data where k='review-bill'),'owner-confirmed done room permits a new v2 bill');
select public.set_settlement_completed(id,true) from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='review-next-bill');
select pg_temp.check(public.create_room_settlement('24000000-0000-4000-8000-000000000001','New legacy bill',2000,'Synthetic','0000','B')<>(select (v#>>'{}')::uuid from s4_data where k='review-next-bill'),'owner-confirmed done room permits another legacy bill');
select pg_temp.check(public.get_settlement_payment_details((select (v#>>'{}')::uuid from s4_data where k='review-bill'))->'payment_details'='null'::jsonb,'new bill never reopens the old closed disclosure');
reset role;
insert into public.dutch_pay_bills(room_id,creator_id,title,total_amount,split_count) values('24000000-0000-4000-8000-000000000002','10000003-0000-4000-8000-000000000003','Trusted trigger fixture',1000,1);
select pg_temp.check((select stage='scheduling' from public.rooms where id='24000000-0000-4000-8000-000000000002'),'settlement trigger itself cannot advance an unconfirmed room');
select pg_temp.check(not has_function_privilege('authenticated','private.s4_settlement_allowed(public.rooms)','EXECUTE') and not has_function_privilege('service_role','private.create_room_settlement_impl(uuid,text,integer,text,text,text,boolean)','EXECUTE'),'settlement predicates and core have narrow ACL');
select * from finish();
rollback;
